//! Encoding parity test: Rust encoding must match Python encoding within 1e-6.
//!
//! Reference data generated by Python:
//!   seed=42, draw_step=1, always take first legal action for 10 moves.
//!   tests/parity_data.json contains 11 snapshots (initial + 10 moves).

use klondike_core::encoding::{encode_state, OBSERVATION_DIM};
use klondike_core::env::KlondikeEnv;

/// Load parity data from JSON. Each entry has "move" (nullable int) and "obs" (757 floats).
fn load_parity_data() -> Vec<(Option<usize>, Vec<f32>)> {
    let data = include_str!("parity_data.json");
    let parsed: serde_json::Value = serde_json::from_str(data).expect("valid JSON");
    let arr = parsed.as_array().expect("top-level array");
    arr.iter()
        .map(|entry| {
            let action = if entry["move"].is_null() {
                None
            } else {
                Some(entry["move"].as_u64().expect("integer action") as usize)
            };
            let obs: Vec<f32> = entry["obs"]
                .as_array()
                .expect("obs array")
                .iter()
                .map(|v| v.as_f64().expect("float") as f32)
                .collect();
            (action, obs)
        })
        .collect()
}

#[test]
fn test_encoding_parity_with_python() {
    let snapshots = load_parity_data();
    assert_eq!(
        snapshots.len(),
        11,
        "expected 11 snapshots (initial + 10 moves)"
    );

    let mut env = KlondikeEnv::new(42, 1);
    let mut rust_obs = [0.0f32; OBSERVATION_DIM];

    for (step, (action, python_obs)) in snapshots.iter().enumerate() {
        // Apply action (skip for initial state)
        if let Some(a) = action {
            env.step(*a)
                .unwrap_or_else(|e| panic!("step {} action {} failed: {}", step, a, e));
        }

        // Encode current state
        encode_state(env.game(), &mut rust_obs);

        // Compare all 757 floats
        let mut max_diff = 0.0f32;
        let mut worst_idx = 0;
        for (i, (r, p)) in rust_obs.iter().zip(python_obs.iter()).enumerate() {
            let diff = (r - p).abs();
            if diff > max_diff {
                max_diff = diff;
                worst_idx = i;
            }
        }

        assert!(
            max_diff < 1e-6,
            "Step {}: encoding mismatch at index {}: rust={}, python={}, diff={}",
            step,
            worst_idx,
            rust_obs[worst_idx],
            python_obs[worst_idx],
            max_diff
        );
    }
}

#[test]
fn test_legal_actions_match_python() {
    // Verify the first legal action at each step matches Python's sequence
    let expected_first_actions: [usize; 11] =
        [54, 212, 219, 243, 111, 118, 216, 122, 221, 127, 224];

    let mut env = KlondikeEnv::new(42, 1);

    for (step, &expected) in expected_first_actions.iter().enumerate() {
        let actions = env.get_legal_actions();
        assert!(
            !actions.is_empty(),
            "step {}: should have legal actions",
            step
        );
        assert_eq!(
            actions[0], expected,
            "step {}: first legal action mismatch (rust={}, python={})",
            step, actions[0], expected
        );

        // Take the first action (except on the last step)
        if step < 10 {
            env.step(expected)
                .unwrap_or_else(|e| panic!("step {} action {} failed: {}", step, expected, e));
        }
    }
}
